'use strict';
const $=s=>document.querySelector(s),math=PurchaseReportMath;let report=null,request=0;
const time=value=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(value));
function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function invalidate(){request++;report=null;$('#purchase-report-paper').hidden=true;$('#purchase-report-rows').replaceChildren();$('#purchase-report-summary').replaceChildren();$('#purchase-report-print').disabled=true;$('#purchase-report-csv').disabled=true;$('#purchase-report-load').disabled=false;}
function render(data){$('#purchase-report-heading').replaceChildren(node('h2','کاشێر — ڕاپۆرتی کاڵا کڕدراوەکان'),node('p',data.from+' → '+data.to+' · بە کاتی بەغدا'),node('p','کاتی ڕاپۆرت: '+time(data.generated_at)+' · '+data.count+' کاڵا · دراو: IQD'));const summary=$('#purchase-report-summary');for(const [label,key] of [['کۆی پسوولەکان','receipt_count'],['کۆی تێچووی کڕین / IQD','total'],['پارەی دراو لە کاتی کڕین / IQD','paid'],['قەرزی دروستبووی کڕین / IQD','debt_added'],['کڕینی تەنها کۆگا / IQD','untracked_total'],['پسوولەی تەنها کۆگا','untracked_count']]){const group=node('div');group.append(node('dt',label),node('dd',math.money(data.summary[key])));summary.append(group);}data.rows.forEach((r,i)=>{const row=node('tr');for(const value of [i+1,r.name,r.barcode||'—',math.quantity(r.quantity_units),math.money(r.total),math.money(r.receipt_count),time(r.last_purchase_at)])row.append(node('td',String(value)));$('#purchase-report-rows').append(row);});$('#purchase-report-empty').hidden=data.rows.length!==0;$('#purchase-report-paper').hidden=false;}
async function load(){invalidate();const mine=++request,from=$('#purchase-report-from').value,to=$('#purchase-report-to').value;if(!KashierData.loggedIn()){location.replace('auth.html?next=purchase-report.html');return;}try{math.range(from,to);}catch(error){$('#purchase-report-status').textContent=error.message;return;}$('#purchase-report-load').disabled=true;$('#purchase-report-status').textContent='خوێندنەوەی ڕاپۆرت…';try{const data=await KashierData.getPurchaseReport(from,to);if(mine!==request)return;math.validate(data,from,to);render(data);report=data;$('#purchase-report-print').disabled=false;$('#purchase-report-csv').disabled=false;$('#purchase-report-status').textContent='ڕاپۆرتەکە ئامادەیە؛ بۆ مامەڵە نوێکان دووبارە ڕاپۆرت بخوێنەرەوە.';}catch(error){if(mine===request){invalidate();$('#purchase-report-status').textContent=error.message;}}finally{if(mine===request)$('#purchase-report-load').disabled=false;}}
$('#purchase-report-form').addEventListener('submit',event=>{event.preventDefault();load();});for(const selector of ['#purchase-report-from','#purchase-report-to'])$(selector).addEventListener('input',()=>{invalidate();$('#purchase-report-status').textContent='بۆ ماوەی نوێ ڕاپۆرت بخوێنەرەوە.';});$('#purchase-report-print').addEventListener('click',()=>{if(report)window.print();});$('#purchase-report-csv').addEventListener('click',()=>{if(!report)return;const blob=new Blob([math.csv(report,StocktakeExport.cell)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=node('a');link.href=url;link.download='kashier-purchases-'+report.from+'-'+report.to+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),part=type=>parts.find(p=>p.type===type).value,today=part('year')+'-'+part('month')+'-'+part('day');$('#purchase-report-from').value=today.slice(0,8)+'01';$('#purchase-report-to').value=today;load();
